#!/bin/bash
#SBATCH --time=12:00:00
#SBATCH --mem=10G

### Written by Valeria Anorve-Garibay

# apply the GRCh38 masks to each archaic genome
# input: hg38-liftovered high-coverage archaic genomes generated by Laurits Skov (TODO: link)
# $1: archaic genome (AltaiNeandertal, Vindija33.19, Denisova or Chagyrskaya-Phalanx)
# e.g. 'sbatch --array=1-22 03.ApplyMasks.sh Denisova'

# paths
skov_path=/path/to/archaic_genomes/GRCh38/SkovFiles
mask_path=/path/to/archaic_genomes/GRCh38/FilterBed

set -euo pipefail

# load modules
module load bcftools tabix

chrom=${SLURM_ARRAY_TASK_ID}
ARCHAIC=$1

input_vcf=$skov_path/individuals_highcov.${chrom}.vcf.gz
mask_bed=$mask_path/${ARCHAIC}/chr${chrom}_mask_renamed.sorted.bed
out_file=$skov_path/${ARCHAIC}_chr${chrom}_QC.vcf.gz

bcftools view -s ${ARCHAIC} -R ${mask_bed} ${input_vcf} -Oz -o ${out_file}
tabix -p vcf ${out_file}
